import{_ as a,o as i,c as r,a0 as t}from"./chunks/framework.DB31oXgM.js";const u=JSON.parse('{"title":"07 - Frontend Specification: Rollback Netcode Server","description":"","frontmatter":{},"headers":[],"relativePath":"07-frontend-spec.md","filePath":"07-frontend-spec.md"}'),o={name:"07-frontend-spec.md"};function n(s,e,d,c,l,h){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="_07-frontend-specification-rollback-netcode-server" tabindex="-1">07 - Frontend Specification: Rollback Netcode Server <a class="header-anchor" href="#_07-frontend-specification-rollback-netcode-server" aria-label="Permalink to &quot;07 - Frontend Specification: Rollback Netcode Server&quot;">​</a></h1><h2 id="_1-visual-design-tech-stack-specified" tabindex="-1">1. Visual Design &amp; Tech Stack [Specified] <a class="header-anchor" href="#_1-visual-design-tech-stack-specified" aria-label="Permalink to &quot;1. Visual Design &amp; Tech Stack [Specified]&quot;">​</a></h2><ul><li><strong>Framework</strong>: Next.js 14 (App Router) + TypeScript</li><li><strong>Styling</strong>: TailwindCSS with bespoke dark futuristic HUD theme (<code>#0B0E14</code> dark slate, <code>#00F5FF</code> cyan accent, <code>#FF2E93</code> magenta warning).</li><li><strong>Motion &amp; Smooth Scrolling</strong>: Lenis smooth scroll engine coupled with GSAP ScrollTrigger.</li><li><strong>3D &amp; 2D Graphics</strong>: Three.js via <code>@react-three/fiber</code> for hero visualization; HTML5 Canvas for the 60 FPS deterministic 2D arena client.</li></ul><h2 id="_2-page-hierarchy-user-journeys-specified" tabindex="-1">2. Page Hierarchy &amp; User Journeys [Specified] <a class="header-anchor" href="#_2-page-hierarchy-user-journeys-specified" aria-label="Permalink to &quot;2. Page Hierarchy &amp; User Journeys [Specified]&quot;">​</a></h2><h3 id="_2-1-landing-page" tabindex="-1">2.1 Landing Page (<code>/</code>) <a class="header-anchor" href="#_2-1-landing-page" aria-label="Permalink to &quot;2.1 Landing Page (`/`)&quot;">​</a></h3><ul><li><strong>Navigation Bar</strong>: Links to <code>/</code>, <code>/dashboard</code>, <code>/arena</code>, <code>/ai-insights</code>, and &quot;AI Diagnostics&quot; action button.</li><li><strong>Hero Section</strong>: 3D interactive viewport rendering animated arena wireframes.</li><li><strong>Feature Grid</strong>: Detailed breakdown of Q16.16 math, Blake3 checksumming, and rollback ring buffers.</li></ul><h3 id="_2-2-telemetry-dashboard-dashboard" tabindex="-1">2.2 Telemetry Dashboard (<code>/dashboard</code>) <a class="header-anchor" href="#_2-2-telemetry-dashboard-dashboard" aria-label="Permalink to &quot;2.2 Telemetry Dashboard (`/dashboard`)&quot;">​</a></h3><ul><li><strong>Snapshot Ring Buffer Visualizer</strong>: Circular animated SVG gauge representing 128 buffer slots. Slots transition dynamically between <code>Confirmed</code> (Green), <code>Predicted</code> (Cyan), and <code>Rolled-Back</code> (Amber).</li><li><strong>Jitter &amp; RTT Real-Time Graph</strong>: Live timeseries charts tracking raw network transit delay vs Kalman Filter smoothed projections.</li><li><strong>Rollback Rate Monitor</strong>: Displays rolling average resimulation depth (frames rewound per second).</li></ul><h3 id="_2-3-interactive-2d-arena-playground-arena" tabindex="-1">2.3 Interactive 2D Arena Playground (<code>/arena</code>) <a class="header-anchor" href="#_2-3-interactive-2d-arena-playground-arena" aria-label="Permalink to &quot;2.3 Interactive 2D Arena Playground (`/arena`)&quot;">​</a></h3><ul><li><strong>Canvas Renderer</strong>: Displays player avatars, physics bounding boxes, projectile trajectories, and authoritative server &quot;ghost&quot; positions.</li><li><strong>Network Impairment Injector</strong>: Interactive sliders to simulate artificial latency (0 - 300 ms), packet loss (0 - 50%), and jitter (0 - 100 ms).</li></ul><h3 id="_2-4-ai-diagnostics-explainer-studio-ai-insights" tabindex="-1">2.4 AI Diagnostics &amp; Explainer Studio (<code>/ai-insights</code>) <a class="header-anchor" href="#_2-4-ai-diagnostics-explainer-studio-ai-insights" aria-label="Permalink to &quot;2.4 AI Diagnostics &amp; Explainer Studio (`/ai-insights`)&quot;">​</a></h3><ul><li><strong>Cheat Detection Panel</strong>: Scatter plot of input velocity vectors with decision boundaries generated by the Isolation Forest model.</li><li><strong>Desync Diff Explorer</strong>: Side-by-side JSON diff viewer highlighting mismatched state variables with one-click &quot;Explain with AI&quot; LLM diagnosis.</li></ul>',12)])])}const p=a(o,[["render",n]]);export{u as __pageData,p as default};
